import org.apache.commons.io.input.UnsynchronizedBufferedReader;
import java.io.StringReader;
public class scratch_T {
    public static void main(String[] args) throws Exception {
        UnsynchronizedBufferedReader r = new UnsynchronizedBufferedReader(new StringReader("abc"));
        try {
            r.reset();
            System.out.println("reset without mark: no exception");
        } catch (Exception e) {
            System.out.println("reset without mark threw: " + e);
        }
        UnsynchronizedBufferedReader r2 = new UnsynchronizedBufferedReader(new StringReader("abcdef"));
        char[] buf = new char[10];
        r2.read();
        int len1 = r2.read(buf, 0, 10);
        System.out.println("len1=" + len1);
        int len2 = r2.read(buf, 0, 10);
        System.out.println("len2(at eof)=" + len2);
    }
}
